	edges = append(edges, Edge{v, cap, cost, head[u]})
	head[u] = idx
	edges = append(edges, Edge{u, 0, -cost, head[v]})
	head[v] = idx + 1
}

func mcmf(S, T int) (int, int) {
	flow, cost := 0, 0
	d := make([]int, nv)
	p := make([]int, nv)
	inqueue := make([]bool, nv)

