		for(int j = 1; j <= m; ++j) {
			if(group(i, j) == 0)
				addEdge(S, id(i, j), 1, 0);
			else
				addEdge(id(i, j), T, 1, 0);
		}
	for(int i = 1; i <= n; ++i) {
		for(int j = 1; j <= m; ++j) {
			if(group(i, j) == 0) {
				if(i-1 >= 1)
					addEdge(id(i, j), id(i-1, j), 1, A[i][j] != A[i-1][j]);
				if(i+1 <= n)
					addEdge(id(i, j), id(i+1, j), 1, A[i][j] != A[i+1][j]);
				if(j-1 >= 1)
					addEdge(id(i, j), id(i, j-1), 1, A[i][j] != A[i][j-1]);
				if(j+1 <= m)
					addEdge(id(i, j), id(i, j+1), 1, A[i][j] != A[i][j+1]);
			}
		}
	}
	auto ans = mcmf(S, T);
	cout << ans.second << endl;
	return 0;
}
